  const barrel = new THREE.Mesh(new THREE.CylinderGeometry(.035, .035, .7, 6), mat('barrel', '#202622')); barrel.rotation.x = Math.PI / 2; barrel.position.set(0, .02, -.95); gun.add(barrel);
